        int x1 = path[0];
        int y1 = path[1];
        int x2 = path[2];
        int y2 = path[3];
        grid[x1][y1] = true;
        grid[x2][y2] = true;
    }
    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
