    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(boolean[][] grid, int x, int y, int endX, int endY, boolean[][] visited) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || visited[x][y] || !grid[x][y]) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    if (dfs(grid, x + 1, y, endX, endY, visited) ||
        dfs(grid, x - 1, y, endX, endY, visited) ||
        dfs(grid, x, y + 1, endX, endY, visited) ||
        dfs(grid, x, y - 1, endX, endY, visited)) {
        return true;
    }
    visited[x][y] = false;
    return false;
}

