public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) return result;

        Queue<Integer> que = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            que.offer(i);
        }

        while (!que.isEmpty()) {
            int num = que.poll();
            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) continue;
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                que.offer(num * 10 + (lastDigit - 1));
            }
            if (lastDigit < 9) {
                que.offer(num * 10 + (lastDigit + 1));
            }
        }

        Collections.sort(result);
        return result;
    }

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long divider = i * 10;
        long higher = n / divider;
        long current = (n / i) % 10;
        long lower = n % i;

        if (current == 0) {
            count += higher * i;
        } else if (current == 1) {
            count += higher * i + lower + 1;
        } else {
            count += (higher + 1) * i;
        }
    }

    return count;
}

