public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    int[][] dp = new int[n][1 << n];
    for (int[] row : dp) {
        Arrays.fill(row, -1);
    }

    return backtrack(A, 0, 0, dp);
}

private static int backtrack(int[] A, int index, int mask, int[][] dp) {
    if (index == A.length) {
        return 1;
    }

    if (dp[index][mask] != -1) {
        return dp[index][mask];
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if ((mask & (1 << i)) == 0) {
            int sum = A[index] + A[i];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                count += backtrack(A, index + 1, mask | (1 << i), dp);
            }
        }
    }

    dp[index][mask] = count;
    return count;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    Stack<Integer> stack = new Stack<>();

    // Fill left array
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        left[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }

    // Clear stack for reuse
    stack.clear();

    // Fill right array
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        right[i] = stack.isEmpty() ? n : stack.peek();
        stack.push(i);
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Traverse up
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r--][c++];
            }
        } else {
            // Traverse down
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (c >= 0 && r < rows) {
                result[index++] = mat[r++][c--];
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first digit that can be swapped to get a larger number
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of (i) which is greater than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < len; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }

            // Swap the found digit with digits[i]
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits after the (i)th position
            Arrays.sort(digits, i + 1, len);

            // Convert the digits back to number
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such digit is found, return -1
    return -1;
}

